-- Seed gerada a partir dos catálogos locais do construtor.
-- Idempotente por ID; nunca remove registros de outro sistema/ruleset.
on conflict (id) do update set name_pt=excluded.name_pt,item_category=excluded.item_category,ruleset=excluded.ruleset,source_book=excluded.source_book,source_page=excluded.source_page,data=excluded.data,system_id=excluded.system_id,updated_at=now();

on conflict (id) do update set name_pt=excluded.name_pt,rank=excluded.rank,is_cantrip=excluded.is_cantrip,is_focus=excluded.is_focus,ruleset=excluded.ruleset,source_book=excluded.source_book,source_page=excluded.source_page,data=excluded.data,system_id=excluded.system_id,updated_at=now();

on conflict (id) do update set feat_type=excluded.feat_type,level=excluded.level,name_pt=excluded.name_pt,ruleset=excluded.ruleset,source_book=excluded.source_book,source_page=excluded.source_page,data=excluded.data,system_id=excluded.system_id,updated_at=now();
